<?php

declare(strict_types=1);

namespace Eventor\Shared\Domain\Id;

use Symfony\Component\Uid\Uuid;

/**
 * Typed UUIDv7 identifier. A module adds its own id with two lines:
 *
 *     final readonly class OrderId extends AbstractId {}
 *     final class OrderIdType extends AbstractIdType { public const string NAME = 'order_id'; protected function idClass(): string { return OrderId::class; } }
 *
 * and registers the DBAL type in its services.php (`ModuleServices::dbalTypes()`). Ids are time-ordered,
 * generated by the application and compared by value and class (an OrderId never equals a PersonId).
 */
abstract readonly class AbstractId implements \Stringable, \JsonSerializable
{
    final protected function __construct(private string $value) {}

    public static function generate(): static
    {
        return new static(Uuid::v7()->toRfc4122());
    }

    public static function fromString(string $value): static
    {
        if (!Uuid::isValid($value)) {
            throw new \InvalidArgumentException(\sprintf('"%s" is not a valid %s.', $value, static::class));
        }

        return new static(strtolower(Uuid::fromString($value)->toRfc4122()));
    }

    public static function isValid(string $value): bool
    {
        return Uuid::isValid($value);
    }

    public function toString(): string
    {
        return $this->value;
    }

    public function toUuid(): Uuid
    {
        return Uuid::fromString($this->value);
    }

    public function equals(self $other): bool
    {
        return $other::class === static::class && $other->value === $this->value;
    }

    public function __toString(): string
    {
        return $this->value;
    }

    public function jsonSerialize(): string
    {
        return $this->value;
    }
}
